const row = $input.first().json;
const QUOTA = { trial: 150, start: 300, business: 1000, network: 3000, none: 0 };
const plan = row.plan || 'trial';
return [{
  json: {
    success: true,
    plan,
    status: row.status || 'trialing',
    quota: QUOTA[plan] ?? 0,
    used: Number(row.used) || 0,
    topupBalance: Number(row.topup_balance) || 0,
    botsRegistered: Number(row.bots_registered) || 0,
    channelsConnected: Number(row.channels_connected) || 0,
    periodEnd: row.period_end ?? null,
  },
}];
